begin;
create table public.notes_folders(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,parent_folder_id uuid references public.notes_folders(id) on delete cascade,title text not null check(char_length(title) between 1 and 120),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index notes_folders_owner_parent_idx on public.notes_folders(owner_id,parent_folder_id,created_at);
create table public.notes_documents(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,folder_id uuid references public.notes_folders(id) on delete cascade,title text not null default 'Senza titolo' check(char_length(title) between 1 and 160),content_html text not null default '' check(char_length(content_html)<=300000),updated_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index notes_documents_owner_folder_idx on public.notes_documents(owner_id,folder_id,updated_at desc);
create table public.notes_collaborators(id uuid primary key default gen_random_uuid(),resource_type text not null check(resource_type in('FOLDER','DOCUMENT')),folder_id uuid references public.notes_folders(id) on delete cascade,document_id uuid references public.notes_documents(id) on delete cascade,owner_id uuid not null references auth.users(id) on delete cascade,invited_user_id uuid not null references auth.users(id) on delete cascade,invited_by uuid not null references auth.users(id) on delete cascade,status text not null default 'PENDING' check(status in('PENDING','ACCEPTED','DECLINED','REVOKED')),created_at timestamptz not null default now(),responded_at timestamptz,constraint notes_collaborator_resource_check check((resource_type='FOLDER' and folder_id is not null and document_id is null) or (resource_type='DOCUMENT' and document_id is not null and folder_id is null)),constraint notes_collaborator_not_self check(owner_id<>invited_user_id));
create unique index notes_folder_collaborator_unique on public.notes_collaborators(folder_id,invited_user_id) where resource_type='FOLDER';
create unique index notes_document_collaborator_unique on public.notes_collaborators(document_id,invited_user_id) where resource_type='DOCUMENT';
create index notes_collaborators_invitee_status_idx on public.notes_collaborators(invited_user_id,status,created_at desc);
create or replace function private.notes_is_platform_owner(p_user_id uuid default auth.uid()) returns boolean language sql stable security definer set search_path=pg_catalog,public as $$select exists(select 1 from public.profiles p where p.id=p_user_id and p.role::text='OWNER' and p.status::text='APPROVED');$$;
create or replace function private.notes_can_access_folder(p_folder_id uuid,p_user_id uuid default auth.uid()) returns boolean language sql stable security definer set search_path=pg_catalog,public,private as $$select p_folder_id is not null and (private.notes_is_platform_owner(p_user_id) or exists(select 1 from public.notes_folders f where f.id=p_folder_id and f.owner_id=p_user_id) or exists(with recursive ancestors(id,parent_folder_id) as (select f.id,f.parent_folder_id from public.notes_folders f where f.id=p_folder_id union all select parent.id,parent.parent_folder_id from public.notes_folders parent join ancestors a on a.parent_folder_id=parent.id) select 1 from public.notes_collaborators c join ancestors a on a.id=c.folder_id where c.resource_type='FOLDER' and c.invited_user_id=p_user_id and c.status='ACCEPTED'));$$;
create or replace function private.notes_can_access_document(p_document_id uuid,p_user_id uuid default auth.uid()) returns boolean language sql stable security definer set search_path=pg_catalog,public,private as $$select p_document_id is not null and (private.notes_is_platform_owner(p_user_id) or exists(select 1 from public.notes_documents d where d.id=p_document_id and d.owner_id=p_user_id) or exists(select 1 from public.notes_collaborators c where c.resource_type='DOCUMENT' and c.document_id=p_document_id and c.invited_user_id=p_user_id and c.status='ACCEPTED') or exists(select 1 from public.notes_documents d where d.id=p_document_id and d.folder_id is not null and private.notes_can_access_folder(d.folder_id,p_user_id)));$$;
create or replace function private.notes_can_edit_document(p_document_id uuid,p_user_id uuid default auth.uid()) returns boolean language sql stable security definer set search_path=pg_catalog,public,private as $$select p_document_id is not null and not private.notes_is_platform_owner(p_user_id) and (exists(select 1 from public.notes_documents d where d.id=p_document_id and d.owner_id=p_user_id) or exists(select 1 from public.notes_collaborators c where c.resource_type='DOCUMENT' and c.document_id=p_document_id and c.invited_user_id=p_user_id and c.status='ACCEPTED') or exists(select 1 from public.notes_documents d where d.id=p_document_id and d.folder_id is not null and private.notes_can_access_folder(d.folder_id,p_user_id)));$$;
create or replace function private.notes_touch_updated_at() returns trigger language plpgsql set search_path=pg_catalog,public as $$begin new.updated_at=now();return new;end;$$;
create trigger notes_folders_touch_updated_at before update on public.notes_folders for each row execute function private.notes_touch_updated_at();
create trigger notes_documents_touch_updated_at before update on public.notes_documents for each row execute function private.notes_touch_updated_at();
alter table public.notes_folders enable row level security;alter table public.notes_documents enable row level security;alter table public.notes_collaborators enable row level security;
create policy notes_folders_read_access on public.notes_folders for select to authenticated using(private.notes_can_access_folder(id,(select auth.uid())));
create policy notes_folders_insert_access on public.notes_folders for insert to authenticated with check(owner_id=(select auth.uid()) and (parent_folder_id is null or private.notes_can_access_folder(parent_folder_id,(select auth.uid()))));
create policy notes_folders_update_owner on public.notes_folders for update to authenticated using(owner_id=(select auth.uid())) with check(owner_id=(select auth.uid()));
create policy notes_folders_delete_owner on public.notes_folders for delete to authenticated using(owner_id=(select auth.uid()));
create policy notes_documents_read_access on public.notes_documents for select to authenticated using(private.notes_can_access_document(id,(select auth.uid())));
create policy notes_documents_insert_access on public.notes_documents for insert to authenticated with check(owner_id=(select auth.uid()) and (folder_id is null or private.notes_can_access_folder(folder_id,(select auth.uid()))));
create policy notes_documents_update_access on public.notes_documents for update to authenticated using(private.notes_can_edit_document(id,(select auth.uid()))) with check(private.notes_can_edit_document(id,(select auth.uid())));
create policy notes_documents_delete_owner on public.notes_documents for delete to authenticated using(owner_id=(select auth.uid()) or exists(select 1 from public.notes_folders f where f.id=folder_id and f.owner_id=(select auth.uid())));
create policy notes_collaborators_read_participant on public.notes_collaborators for select to authenticated using(invited_user_id=(select auth.uid()) or owner_id=(select auth.uid()) or invited_by=(select auth.uid()) or private.notes_is_platform_owner((select auth.uid())));
revoke all on public.notes_folders,public.notes_documents,public.notes_collaborators from anon,authenticated;
grant select,insert,update,delete on public.notes_folders,public.notes_documents to authenticated;
grant select on public.notes_collaborators to authenticated;
create or replace function public.renqd_invite_notes_collaborator(p_resource_type text,p_resource_id uuid,p_username text) returns uuid language plpgsql security definer set search_path=pg_catalog,public,private as $$
declare v_actor uuid:=auth.uid();v_target uuid;v_owner uuid;v_title text;v_invite_id uuid;v_resource_type text:=upper(trim(p_resource_type));v_actor_username text;
begin
if v_actor is null or not private.is_approved_user() then raise exception 'Account non autorizzato' using errcode='42501';end if;
if v_resource_type not in('FOLDER','DOCUMENT') then raise exception 'Tipo di contenuto non valido';end if;
select id into v_target from public.profiles where lower(username)=lower(trim(p_username)) and status::text='APPROVED';
if v_target is null then raise exception 'Utente Renqd non trovato o non approvato';end if;
if v_target=v_actor then raise exception 'Non puoi invitare te stesso';end if;
select username into v_actor_username from public.profiles where id=v_actor;
if v_resource_type='FOLDER' then select owner_id,title into v_owner,v_title from public.notes_folders where id=p_resource_id;else select owner_id,title into v_owner,v_title from public.notes_documents where id=p_resource_id;end if;
if v_owner is distinct from v_actor then raise exception 'Solo il proprietario può invitare collaboratori' using errcode='42501';end if;
if v_resource_type='FOLDER' then insert into public.notes_collaborators(resource_type,folder_id,owner_id,invited_user_id,invited_by,status) values('FOLDER',p_resource_id,v_actor,v_target,v_actor,'PENDING') on conflict(folder_id,invited_user_id) where resource_type='FOLDER' do update set invited_by=excluded.invited_by,owner_id=excluded.owner_id,status='PENDING',responded_at=null,created_at=now() returning id into v_invite_id;
else insert into public.notes_collaborators(resource_type,document_id,owner_id,invited_user_id,invited_by,status) values('DOCUMENT',p_resource_id,v_actor,v_target,v_actor,'PENDING') on conflict(document_id,invited_user_id) where resource_type='DOCUMENT' do update set invited_by=excluded.invited_by,owner_id=excluded.owner_id,status='PENDING',responded_at=null,created_at=now() returning id into v_invite_id;end if;
insert into public.user_notifications(recipient_id,actor_id,notification_type,payload) values(v_target,v_actor,'NOTES_INVITATION',jsonb_build_object('inviteId',v_invite_id,'resourceType',v_resource_type,'resourceId',p_resource_id,'resourceTitle',v_title,'actorUsername',v_actor_username));return v_invite_id;end;$$;
create or replace function public.renqd_respond_notes_invitation(p_invite_id uuid,p_accept boolean) returns void language plpgsql security definer set search_path=pg_catalog,public,private as $$
declare v_invite public.notes_collaborators%rowtype;
begin
if auth.uid() is null or not private.is_approved_user() then raise exception 'Account non autorizzato' using errcode='42501';end if;
select * into v_invite from public.notes_collaborators where id=p_invite_id and invited_user_id=auth.uid() for update;
if not found or v_invite.status<>'PENDING' then raise exception 'Invito non disponibile';end if;
update public.notes_collaborators set status=case when p_accept then 'ACCEPTED' else 'DECLINED' end,responded_at=now() where id=p_invite_id;
update public.user_notifications set read_at=coalesce(read_at,now()) where recipient_id=auth.uid() and notification_type='NOTES_INVITATION' and payload->>'inviteId'=p_invite_id::text;end;$$;
create or replace function public.renqd_revoke_notes_invitation(p_invite_id uuid) returns void language plpgsql security definer set search_path=pg_catalog,public,private as $$
begin
if auth.uid() is null or not private.is_approved_user() then raise exception 'Account non autorizzato' using errcode='42501';end if;
update public.notes_collaborators set status='REVOKED',responded_at=now() where id=p_invite_id and owner_id=auth.uid() and status in('PENDING','ACCEPTED');
if not found then raise exception 'Invito non disponibile o non gestibile' using errcode='42501';end if;end;$$;
revoke all on function public.renqd_invite_notes_collaborator(text,uuid,text) from public,anon;
revoke all on function public.renqd_respond_notes_invitation(uuid,boolean) from public,anon;
revoke all on function public.renqd_revoke_notes_invitation(uuid) from public,anon;
grant execute on function public.renqd_invite_notes_collaborator(text,uuid,text) to authenticated;
grant execute on function public.renqd_respond_notes_invitation(uuid,boolean) to authenticated;
grant execute on function public.renqd_revoke_notes_invitation(uuid) to authenticated;
do $$begin if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='notes_documents') then alter publication supabase_realtime add table public.notes_documents;end if;if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='notes_folders') then alter publication supabase_realtime add table public.notes_folders;end if;end$$;
commit;